def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    if W >= H:
        n = H
        halves = [g[:, :n], g[:, n:2*n]]
    else:
        n = W
        halves = [g[:n, :], g[n:2*n, :]]

    def ncols(h):
        return len(set(h[h != bg].tolist()))

    if (halves[0] == 8).any() and not (halves[1] == 8).any():
        si = 0
    elif (halves[1] == 8).any() and not (halves[0] == 8).any():
        si = 1
    else:
        si = 0 if ncols(halves[0]) <= ncols(halves[1]) else 1
    shape = halves[si] != bg
    pattern = halves[1 - si]

    out = np.full((n * n, n * n), bg, dtype=int)
    emit(out, f"Allocate an empty {n*n}x{n*n} canvas: one {n}x{n} block per pattern cell.")
    for r in range(n):
        for c in range(n):
            col = pattern[r, c]
            if col != bg:
                block = out[r*n:(r+1)*n, c*n:(c+1)*n]
                block[shape] = col
        emit(out, f"Stamp the shape, recoloured by each pattern cell of row {r}, into block row {r}.")
    emit(out, "Final: every coloured pattern cell has become a copy of the shape in that colour.")
    return out
